package io.aetheris.orchestrator.voice;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity @Table(name="aetheris_voice_turn_metrics") public class VoiceTurnMetricEntity {@Id private UUID id;@Column(nullable=false) private UUID sessionId;private long vadStartMs;private long speechEndMs;private long firstPartialMs;private long finalTranscriptMs;private long ttsStartMs;private long bargeInMs;private long ttsStoppedMs;private long partialLatencyMs;private long finalLatencyMs;private long bargeInStopLatencyMs;@Column(nullable=false) private Instant createdAt;protected VoiceTurnMetricEntity(){}public VoiceTurnMetricEntity(UUID id,VoiceTurnMetricRequest r){this.id=id;this.sessionId=r.sessionId();this.vadStartMs=r.vadStartMs();this.speechEndMs=r.speechEndMs();this.firstPartialMs=r.firstPartialMs();this.finalTranscriptMs=r.finalTranscriptMs();this.ttsStartMs=r.ttsStartMs();this.bargeInMs=r.bargeInMs();this.ttsStoppedMs=r.ttsStoppedMs();this.partialLatencyMs=delta(r.speechEndMs(),r.firstPartialMs());this.finalLatencyMs=delta(r.speechEndMs(),r.finalTranscriptMs());this.bargeInStopLatencyMs=delta(r.bargeInMs(),r.ttsStoppedMs());this.createdAt=Instant.now();}private long delta(long a,long b){return a>0&&b>=a?b-a:-1;}public UUID getId(){return id;}public UUID getSessionId(){return sessionId;}public long getPartialLatencyMs(){return partialLatencyMs;}public long getFinalLatencyMs(){return finalLatencyMs;}public long getBargeInStopLatencyMs(){return bargeInStopLatencyMs;}public Instant getCreatedAt(){return createdAt;}}
